package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real store/templates, executor double and modeled manager: no connected tenant authorization. */
class SqlServerOrganizationStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",TIME="2026-11-04T00:00:00.123456Z";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerOrganizationStore store=new SqlServerOrganizationStore(executor,manager);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/organization");final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerOrganizationStoreTest(){actor("ADM","CLINIC","HUMAN");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());calls.add(inv.getArgument(0));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void actor(String role,String kind,String domain){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of(role),"a".repeat(64)));request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic",kind,domain,"ACTIVE",List.of("CORE")));}
 void rows(List<Map<String,Object>> rows){results.add(new SqlServerExecutor.Result(List.of(rows),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());}
 static Map<String,Object> identity(){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("name","Synthetic");r.put("email","qa@example.test");r.put("clinicalDomain",null);r.put("credential",null);return r;}
 static Map<String,Object> directory(){return new LinkedHashMap<>(Map.of("id",ID,"name","Sede","address","","external",false,"active",true));}
 static Map<String,Object> professional(){var r=identity();r.remove("email");r.put("roles",new ArrayList<>(List.of("ADM","PRO")));return r;}
 static Map<String,Object> plan(){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("planId",ID);r.put("name","Synthetic clinic");r.put("description","");r.put("status","PUBLISHED");r.put("currentVersion",1);r.put("version",1);r.put("baseMinor",1000000000000L);r.put("branchMinor",0L);r.put("professionalMinor",0L);for(String suffix:List.of("Branches","Professionals","Specialties")){r.put("included"+suffix,1);r.put("max"+suffix,10);}r.put("annualDiscount",60);r.put("kinds",List.of("CLINIC"));r.put("domains",List.of("HUMAN"));r.put("modules",List.of("CORE","PORTAL"));r.put("createdAt",TIME);return r;}
 static Map<String,Object> realSpecialty() throws Exception {String sql;try(var in=SqlServerOrganizationStoreTest.class.getResourceAsStream("/db/sqlserver/V2__catalog_seed.sql")){sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);}String line=sql.lines().filter(s->s.startsWith("INSERT INTO dbo.specialties") && s.contains(",N'HUMAN',1,")).max(Comparator.comparingInt(String::length)).orElseThrow();StringBuilder json=new StringBuilder();var matcher=java.util.regex.Pattern.compile("N'((?:''|[^'])*)'").matcher(line.substring(line.indexOf("CAST(N'")));while(matcher.find())json.append(matcher.group(1).replace("''","'"));assertTrue(json.length()>4000);var profile=new tools.jackson.databind.ObjectMapper().readValue(json.toString(),Map.class);var out=new LinkedHashMap<String,Object>();out.put("code",profile.get("code"));out.put("name",profile.get("name"));out.put("domain",profile.get("patientDomain"));out.put("dental",line.substring(0,line.indexOf("CAST(N'")).endsWith(",1,"));out.put("profile",profile);return out;}

 @Test void exactFiveSpPositionalArgsLowercaseNoTrimAndNoInventedLimit() throws Exception {rows(List.of(identity()));assertEquals(5,store.lookup(request," I@EXAMPLE.TEST ").getFirst().size());rows(List.of(directory()));assertEquals(5,store.directory(request).getFirst().size());rows(List.of(professional()));assertEquals(5,store.professionals(request,null).getFirst().size());var specialty=realSpecialty();actor("ADM",specialty.get("domain").equals("HUMAN")?"CLINIC":"VETERINARY",(String)specialty.get("domain"));rows(List.of(specialty));assertEquals(5,store.catalog(request).getFirst().size());actor("ADM","CLINIC","HUMAN");rows(List.of(plan()));assertEquals(21,store.availablePlans(request).getFirst().size());assertEquals(List.of(SqlServerProcedure.ORGANIZATION_LOOKUP,SqlServerProcedure.ORGANIZATION_DIRECTORY,SqlServerProcedure.ORGANIZATION_PROFESSIONALS,SqlServerProcedure.ORGANIZATION_CATALOG,SqlServerProcedure.ORGANIZATION_PLANS),calls);assertEquals(List.of(" i@example.test "),args.getFirst());assertEquals(List.of(),args.get(1));assertEquals(Arrays.asList((Object)null),args.get(2));assertEquals(List.of(),args.get(3));assertEquals(List.of(),args.get(4));rows(Collections.nCopies(250,directory()));assertEquals(250,store.directory(request).size());rows(Collections.nCopies(250,plan()));assertEquals(250,store.availablePlans(request).size());rows(List.of());store.professionals(request,ID);assertEquals(List.of(ID),args.getLast());}
 @Test void emailBoundaryAndBadBranchRejectBeforeSp(){rows(List.of());store.lookup(request,"X".repeat(254));assertEquals(List.of("x".repeat(254)),args.getFirst());assertEquals(400,assertThrows(ApiException.class,()->store.lookup(request,null)).status);assertEquals(400,assertThrows(ApiException.class,()->store.lookup(request,"x".repeat(255))).status);assertEquals(400,assertThrows(ApiException.class,()->store.professionals(request,"bad")).status);assertEquals(1,calls.size());}
 @Test void nullableProjectionsOmitSecretsAndCollectionsAreDeepImmutable() throws Exception {var identity=identity();identity.put("passwordHash","private");rows(List.of(identity));var mapped=store.lookup(request,"qa@example.test");assertEquals(5,mapped.getFirst().size());assertNull(mapped.getFirst().get("clinicalDomain"));assertTrue(mapped.getFirst().containsKey("credential"));assertFalse(mapped.toString().contains("private"));assertThrows(UnsupportedOperationException.class,mapped::clear);assertThrows(UnsupportedOperationException.class,mapped.getFirst()::clear);var pro=professional();pro.put("email","private");rows(List.of(pro));var out=store.professionals(request,null).getFirst();((List<?>)pro.get("roles")).clear();assertEquals(List.of("ADM","PRO"),out.get("roles"));assertThrows(UnsupportedOperationException.class,((List<?>)out.get("roles"))::clear);var specialty=realSpecialty();actor("ADM",specialty.get("domain").equals("HUMAN")?"CLINIC":"VETERINARY",(String)specialty.get("domain"));var profile=new LinkedHashMap<String,Object>();((Map<?,?>)specialty.get("profile")).forEach((key,value)->profile.put((String)key,value));profile.put("synthetic",Arrays.asList(null,new BigDecimal("99999999999999999999.123456"),"text"));specialty.put("profile",profile);specialty.put("private","private");rows(List.of(specialty));var catalog=store.catalog(request).getFirst();assertEquals(profile,catalog.get("profile"));var nested=(List<?>)((Map<?,?>)catalog.get("profile")).get("synthetic");assertNull(nested.getFirst());assertEquals(new BigDecimal("99999999999999999999.123456"),nested.get(1));assertThrows(UnsupportedOperationException.class,nested::clear);assertThrows(UnsupportedOperationException.class,((Map<?,?>)catalog.get("profile"))::clear);assertEquals(5,catalog.size());}
 @Test void directoryMustBeActiveBooleanAndProfessionalsRequireValidProRoles(){for(var change:List.of(Map.entry("active",false),Map.entry("active",1),Map.entry("external",1),Map.entry("id","bad"))){var row=directory();row.put(change.getKey(),change.getValue());rows(List.of(row));safe(()->store.directory(request));}for(Object roles:Arrays.asList(null,List.of(),List.of("ADM"),List.of("PRO","SAD"),List.of("PRO",1))){var row=professional();row.put("roles",roles);rows(List.of(row));safe(()->store.professionals(request,null));}assertEquals("rollback",manager.events.getLast());}
 @Test void catalogMustMatchHostDomainAndDentalWithoutFiltering() throws Exception {var s=realSpecialty();s.put("domain","ANIMAL");rows(List.of(s));safe(()->store.catalog(request));actor("PRO","DENTAL","HUMAN");s=realSpecialty();s.put("domain","HUMAN");s.put("dental",false);rows(List.of(s));safe(()->store.catalog(request));s.put("dental",true);rows(List.of(s));assertEquals(true,store.catalog(request).getFirst().get("dental"));s=new LinkedHashMap<>(s);s.put("profile","not object");rows(List.of(s));safe(()->store.catalog(request));}
 @Test void planPublicationHostKindDomainAndDoctorOneAreValidated(){for(var change:List.of(Map.entry("status","DRAFT"),Map.entry("kinds",List.of("VETERINARY")),Map.entry("domains",List.of("ANIMAL")),Map.entry("planId",TENANT),Map.entry("currentVersion",2),Map.entry("maxBranches",0),Map.entry("annualDiscount",61),Map.entry("baseMinor",1),Map.entry("modules",List.of("PORTAL")),Map.entry("createdAt","2026-11-04T00:00:00.123456789Z"))){var row=plan();row.put(change.getKey(),change.getValue());rows(List.of(row));safe(()->store.availablePlans(request));}actor("ADM","DOCTOR","HUMAN");var row=plan();row.put("kinds",List.of("DOCTOR"));rows(List.of(row));assertEquals(1,store.availablePlans(request).getFirst().get("includedProfessionals"));row=plan();row.put("kinds",List.of("DOCTOR"));row.put("includedProfessionals",4);rows(List.of(row));safe(()->store.availablePlans(request));}
 @Test void allColumnsAndResultSetsAreRequiredNoFakeEmptySuccess() throws Exception {for(String key:identity().keySet()){var r=identity();r.remove(key);rows(List.of(r));safe(()->store.lookup(request,"qa@example.test"));}for(String key:directory().keySet()){var r=directory();r.remove(key);rows(List.of(r));safe(()->store.directory(request));}for(String key:professional().keySet()){var r=professional();r.remove(key);rows(List.of(r));safe(()->store.professionals(request,null));}for(String key:plan().keySet()){var r=plan();r.remove(key);rows(List.of(r));safe(()->store.availablePlans(request));}var specialty=realSpecialty();for(String key:specialty.keySet()){var r=new LinkedHashMap<>(specialty);r.remove(key);rows(List.of(r));safe(()->store.catalog(request));}results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.directory(request));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.directory(request));rows(List.of());assertTrue(store.directory(request).isEmpty());}
 @Test void authorityAdminAndHostUuidTokenAreRevalidatedDirectly(){actor("PRO","CLINIC","HUMAN");assertEquals(403,assertThrows(ApiException.class,()->store.lookup(request,"x")).status);assertEquals(403,assertThrows(ApiException.class,()->store.availablePlans(request)).status);request.setAttribute("health.tenant","bad");safe(()->store.directory(request));actor("ADM","CLINIC","HUMAN");request.setAttribute("health.actor",new Actor("bad","Synthetic","qa@example.test",TENANT,List.of("ADM"),"a".repeat(64)));safe(()->store.directory(request));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("ADM"),"bad"));safe(()->store.directory(request));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",ID,List.of("ADM"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,()->store.directory(request)).status);safe(()->store.directory(null));verifyNoInteractions(executor);}
 @Test void requiredJoinRollbackCommitAndVendorErrorsDoNotRetry(){rows(List.of(directory()));assertThrows(RuntimeException.class,()->manager.outer(()->{store.directory(request);assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("cancel");}));assertEquals("rollback",manager.events.getLast());rows(List.of(directory()));manager.failCommit=true;safe(()->store.directory(request));for(int code:List.of(51001,51002)){doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,code))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.directory(request));assertEquals(code==51001?403:404,e.status);assertFalse(e.toString().contains("private"));}verify(executor,times(4)).execute(any(),any(),any(Object[].class));}
 @Test void jsonInvalidCyclesTypesAndNaNFailWithinTransaction() throws Exception {var cycle=new ArrayList<>();cycle.add(cycle);for(Object invalid:List.of(Map.of("bad",Double.NaN),Map.of("bad",cycle),Map.of(1,"bad"))){var s=realSpecialty();s.put("profile",invalid);rows(List.of(s));safe(()->store.catalog(request));assertEquals("rollback",manager.events.getLast());}}
}
